import numpy as np, math
class Body:
 def __init__(self,p,size,m):
  self.p=np.array(p,float);self.size=np.array(size,float);self.a=0.;self.v=np.zeros(2);self.w=0.;self.im=1/m;self.ii=12/(m*sum(self.size**2))
 def verts(self):
  x,y=self.size/2;c,s=np.cos(self.a),np.sin(self.a);R=np.array([[c,-s],[s,c]])
  return np.array([[-x,-y],[x,-y],[x,y],[-x,y]])@R.T+self.p

def cross(a,b):return a[0]*b[1]-a[1]*b[0]
def clip(pts,n,off):
 d=[np.dot(p,n)-off for p in pts];out=[]
 for p,z in zip(pts,d):
  if z<=0:out.append(p)
 if d[0]*d[1]<0:out.append(pts[0]+(pts[1]-pts[0])*(d[0]/(d[0]-d[1])))
 return out[:2]
def contacts(A,B):
 va,vb=A.verts(),B.verts();best=(-1e9,None,None,None)
 for ref,oth,rev in [(va,vb,False),(vb,va,True)]:
  for i in range(4):
   p,q=ref[i],ref[(i+1)%4];e=q-p;n=np.array([e[1],-e[0]])/np.linalg.norm(e)
   sep=min(oth@n)-np.dot(p,n)
   if sep>0:return []
   if sep>best[0]:best=(sep,i,rev,n)
 sep,idx,rev,n=best;ref,oth=(vb,va) if rev else(va,vb)
 p,q=ref[idx],ref[(idx+1)%4];t=(q-p)/np.linalg.norm(q-p)
 # incident edge
 norms=[]
 for i in range(4):
  e=oth[(i+1)%4]-oth[i];nn=np.array([e[1],-e[0]])/np.linalg.norm(e);norms.append(np.dot(nn,n))
 i=np.argmin(norms);pts=[oth[i],oth[(i+1)%4]]
 pts=clip(pts,-t,-np.dot(p,t))
 if len(pts)<2:return []
 pts=clip(pts,t,np.dot(q,t))
 out=[]
 for pt in pts:
  d=np.dot(pt-p,n)
  if d<=.001:out.append((pt-n*d*.5,-n if rev else n,-d))
 return out
G=Body((0,500),(10000,1000),1);G.im=G.ii=0
bs=[Body((0,-17.5),(16,35),.8),Body((-1,-39),(53,8),.6),Body((19,-71),(12,56),1.)]
def solve(A,B,pt,n,pen,pos=False):
 ra=pt-A.p;rb=pt-B.p
 ca=cross(ra,n);cb=cross(rb,n);k=A.im+B.im+ca*ca*A.ii+cb*cb*B.ii
 if pos:
  j=max(0,pen-.018)*.3/k
  A.p-=j*n*A.im;A.a-=j*ca*A.ii;B.p+=j*n*B.im;B.a+=j*cb*B.ii;return
 va=A.v+A.w*np.array([-ra[1],ra[0]]);vb=B.v+B.w*np.array([-rb[1],rb[0]])
 rel=vb-va;vn=np.dot(rel,n)
 if vn>=0:return
 j=-(1.03 if vn<-15 else 1)*vn/k
 imp=j*n;A.v-=imp*A.im;A.w-=cross(ra,imp)*A.ii;B.v+=imp*B.im;B.w+=cross(rb,imp)*B.ii
 t=np.array([-n[1],n[0]]);cat=cross(ra,t);cbt=cross(rb,t)
 va=A.v+A.w*np.array([-ra[1],ra[0]]);vb=B.v+B.w*np.array([-rb[1],rb[0]])
 jt=-np.dot(vb-va,t)/(A.im+B.im+cat*cat*A.ii+cbt*cbt*B.ii);jt=np.clip(jt,-j*.55,j*.55)
 imp=jt*t;A.v-=imp*A.im;A.w-=cross(ra,imp)*A.ii;B.v+=imp*B.im;B.w+=cross(rb,imp)*B.ii

def simulate():
 states=[];dt=1/240
 for step in range(1201):
  if step%60==0:
   states.append([(b.p.copy(),b.a,b.v.copy(),b.w) for b in bs])
  for b in bs:
   b.v[1]+=280*dt;b.v*=.9998;b.w*=.9998;b.p+=b.v*dt;b.a+=b.w*dt
  cs=[]
  for i,A in enumerate(bs):
   # floor
   for pt in A.verts():
    if pt[1]>0:cs.append((A,G,pt,np.array([0.,1.]),pt[1]))
   for B in bs[i+1:]:
    for pt,n,pen in contacts(A,B):cs.append((A,B,pt,n,pen))
  for iteration in range(10):
   for co in cs:solve(*co)
  for iteration in range(3):
   for co in cs:solve(*co,pos=True)
 return states
